#include <bits/stdc++.h>
using namespace std;

const long long MOD = 1000000007;

long long mod_pow(long long base, long long exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return res;
}

int n;
const int MAX_SIZE = 1 << 20;
int f_arr[MAX_SIZE];
int g_arr[MAX_SIZE];
long long prob_matrix[21][21];
int idx_map[2][MAX_SIZE];
int reverse_mask[MAX_SIZE];
int matched_vertices[21];
bool adj_matrix[21][21];

void compute_func(int* out, const vector<int>& left_nodes, const vector<int>& right_nodes,
                  const vector<int>& subgraphs, int* idx_fn) {
    vector<pair<int, int>> edges;
    for (int u : left_nodes) {
        for (int v : right_nodes) {
            edges.emplace_back(u, v);
        }
    }

    int edge_cnt = edges.size();
    for (int edge_mask = 0; edge_mask < (1 << edge_cnt); ++edge_mask) {
        long long weight = 1;

        for (int i = 0; i < edge_cnt; ++i) {
            int u = edges[i].first;
            int v = edges[i].second;
            if (edge_mask & (1 << i)) {
                weight = (weight * prob_matrix[u][v]) % MOD;
                adj_matrix[u][v] = true;
            } else {
                weight = (weight * ((1 - prob_matrix[u][v] + MOD) % MOD)) % MOD;
                adj_matrix[u][v] = false;
            }
        }

        int new_mask = 0;
        for (int gr : subgraphs) {
            vector<int> left_v(left_nodes.begin(), left_nodes.end());
            vector<int> right_v;
            for (int i = 0; i < n; ++i) {
                if (gr & (1 << i)) right_v.push_back(i + n);
            }

            sort(right_v.begin(), right_v.end());
            bool found = false;
            do {
                bool ok = true;
                for (size_t i = 0; i < left_v.size(); ++i) {
                    if (!adj_matrix[left_v[i]][right_v[i]]) {
                        ok = false;
                        break;
                    }
                }
                if (ok) {
                    found = true;
                    break;
                }
            } while (next_permutation(right_v.begin(), right_v.end()));
            if (found) new_mask |= (1 << idx_fn[gr]);
        }

        out[new_mask] = (out[new_mask] + static_cast<int>(weight)) % MOD;
    }
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);

    cin >> n;
    long long inv100 = mod_pow(100, MOD - 2);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            long long x; cin >> x;
            prob_matrix[i][j + n] = (x * inv100) % MOD;
        }
    }

    if (n == 1) {
        cout << prob_matrix[0][1] << '\n';
        return 0;
    }

    int left_cnt = n / 2;
    int right_cnt = n - left_cnt;

    int count1 = 0, count2 = 0;
    vector<int> sub1, sub2;

    for (int mask = 0; mask < (1 << n); ++mask) {
        if (__builtin_popcount(mask) == left_cnt) {
            idx_map[0][mask] = count1;
            sub1.push_back(mask);
            ++count1;
        }
        if (__builtin_popcount(mask) == right_cnt) {
            idx_map[1][mask] = count2;
            sub2.push_back(mask);
            ++count2;
        }
    }

    for (int i = 0; i < count2; ++i) {
        int mask = sub2[i];
        int comp = ((1 << n) - 1) ^ mask;
        reverse_mask[i] = idx_map[0][comp];
    }

    vector<int> L1, L2, R;
    for (int i = n; i < 2 * n; ++i) R.push_back(i);
    for (int i = 0; i < left_cnt; ++i) L1.push_back(i);
    for (int i = left_cnt; i < n; ++i) L2.push_back(i);

    compute_func(f_arr, L1, R, sub1, idx_map[0]);
    compute_func(g_arr, L2, R, sub2, idx_map[1]);

    int total1 = 1 << count1;
    for (int i = 0; i < count1; ++i) {
        for (int mask = 0; mask < total1; ++mask) {
            if (mask & (1 << i)) {
                f_arr[mask] = (f_arr[mask] + f_arr[mask ^ (1 << i)]) % MOD;
            }
        }
    }

    long long result = 0;
    int total2 = 1 << count2;
    for (int mask = 1; mask < total2; ++mask) {
        int complement = total2 - 1 - mask;
        int reversed = 0;
        for (int i = 0; i < count2; ++i) {
            if (complement & (1 << i)) reversed |= (1 << reverse_mask[i]);
        }

        int inv_complement = (total1 - 1) ^ reversed;
        long long weight = (1 - f_arr[inv_complement] + MOD) % MOD;
        result = (result + weight * g_arr[mask]) % MOD;
    }

    cout << result << '\n';
    return 0;
}
